// src/geo/line.js
var Line4 = class {
  /**
   * Create a line segment between two points
   * @param {Point} p1 - First endpoint
   * @param {Point} p2 - Second endpoint
   * @param {string} [key] - Optional unique identifier (auto-generated from point keys if not provided)
   */
  constructor(p1, p2, key2) {
    if (!key2) key2 = [p1.key, p2.key].join(";");
    this.p1 = p1;
    this.p2 = p2;
    this.key = key2;
  }
  /**
   * Calculate length of line segment in 2D
   * @returns {number} Euclidean distance between endpoints
   */
  length() {
    return Math.sqrt(this.length2());
  }
  /**
   * Calculate squared length of line segment
   * Faster than length() - use when only comparing lengths
   * @returns {number} Squared distance between endpoints
   */
  length2() {
    return this.p1.distToSq2D(this.p2);
  }
  /**
   * Calculate slope of line segment
   * @returns {Slope} Slope object representing direction from p1 to p2
   */
  slope() {
    return base.newSlope(this.p1.slopeTo(this.p2));
  }
  /**
   * Reverse direction of line by swapping endpoints (mutates in place)
   * @returns {Line} This line (for chaining)
   */
  reverse() {
    let t = this.p1;
    this.p1 = this.p2;
    this.p2 = t;
    return this;
  }
  /**
   * Calculate midpoint of line segment
   * @returns {Point} Point at center of line
   */
  midpoint() {
    return this.p1.midPointTo(this.p2);
  }
  /**
   * Check if this line is collinear with another line
   * Uses cross product to test if slopes are parallel within tolerance
   * @param {Line} line - Line to test against
   * @returns {boolean} True if lines are collinear (parallel with same or opposite direction)
   */
  isCollinear(line) {
    let p1 = this.p1, p2 = this.p2, p3 = line.p1, p4 = line.p2, d1x = p2.x - p1.x, d1y = p2.y - p1.y, d2x = p4.x - p3.x, d2y = p4.y - p3.y;
    return Math.abs(d2y * d1x - d2x * d1y) < 1e-4;
  }
};
function newLine(p1, p2, key2) {
  return new Line4(p1, p2, key2);
}
function newOrderedLine(p1, p2, key2) {
  return p1.key < p2.key ? newLine(p1, p2, key2) : newLine(p2, p1, key2);
}

// src/geo/slope.js
var ABS = Math.abs;
var DEG2RAD2 = Math.PI / 180;
var RAD2DEG2 = 180 / Math.PI;
var Slope = class _Slope {
  /**
   * Create slope from two points or explicit dx/dy values
   * @param {Point} [p1] - First point (if creating from points)
   * @param {Point} [p2] - Second point (if creating from points)
   * @param {number} [dx] - X component if not using points
   * @param {number} [dy] - Y component if not using points
   */
  constructor(p1, p2, dx, dy) {
    this.dx = p1 && p2 ? p2.x - p1.x : dx;
    this.dy = p1 && p2 ? p2.y - p1.y : dy;
    this.angle = Math.atan2(this.dy, this.dx) * RAD2DEG2;
  }
  /**
   * Get string representation of slope
   * @returns {string} "dx,dy,angle" format
   */
  toString() {
    return [this.dx, this.dy, this.angle].join(",");
  }
  /**
   * Create deep copy of slope
   * @returns {Slope} New slope with same dx, dy
   */
  clone() {
    return new _Slope(null, null, this.dx, this.dy);
  }
  /**
   * Check if slopes are equivalent within precision tolerance
   * Special handling for near-vertical and near-horizontal slopes
   * Uses adaptive precision based on slope magnitude
   * @param {Slope} s - Slope to compare
   * @returns {boolean} True if slopes are effectively the same
   */
  isSame(s) {
    if (ABS(this.dx) <= config.precision_merge && ABS(s.dx) <= config.precision_merge) return true;
    if (ABS(this.dy) <= config.precision_merge && ABS(s.dy) <= config.precision_merge) return true;
    let prec = Math.min(1 / Math.sqrt(this.dx * this.dx + this.dy * this.dy), config.precision_slope_merge);
    return angleWithinDelta(this.angle, s.angle, prec || config.precision_slope);
  }
  /**
   * Rotate slope 90 degrees counter-clockwise to get perpendicular (mutates in place)
   * Converts slope to its normal (perpendicular) direction
   * @returns {Slope} This slope (for chaining)
   */
  normal() {
    let t = this.dx;
    this.dx = -this.dy;
    this.dy = t;
    this.angle = Math.atan2(this.dy, this.dx) * RAD2DEG2;
    return this;
  }
  /**
   * Reverse slope direction by 180 degrees (mutates in place)
   * Negates both dx and dy components
   * @returns {Slope} This slope (for chaining)
   */
  invert() {
    this.dx = -this.dx;
    this.dy = -this.dy;
    this.angle = Math.atan2(this.dy, this.dx) * RAD2DEG2;
    return this;
  }
  /**
   * Normalize slope so largest component is 1 (mutates in place)
   * Maintains direction while scaling to unit-like form
   * @returns {Slope} This slope (for chaining)
   */
  toUnit() {
    let max2 = Math.max(ABS(this.dx), ABS(this.dy));
    this.dx = this.dx / max2;
    this.dy = this.dy / max2;
    return this;
  }
  /**
   * Scale slope by factor (mutates in place)
   * @param {number} f - Scale factor
   * @returns {Slope} This slope (for chaining)
   */
  factor(f) {
    this.dx *= f;
    this.dy *= f;
    return this;
  }
  /**
   * Calculate angular difference to another slope
   * Result normalized to [-180, 180] range
   * @param {Slope} s2 - Target slope
   * @param {boolean} [sign] - If true, return signed difference; if false, return absolute difference
   * @returns {number} Angle difference in degrees
   */
  angleDiff(s2, sign2) {
    const n1 = this.angle;
    const n2 = s2.angle;
    let diff2 = n2 - n1;
    while (diff2 < -180) diff2 += 360;
    while (diff2 > 180) diff2 -= 360;
    return sign2 ? diff2 : Math.abs(diff2);
  }
};
function angleWithinDelta(a1, a2, delta) {
  return ABS(a1 - a2) <= delta || 360 - ABS(a1 - a2) <= delta;
}
function newSlope(p1, p2, dx, dy) {
  return new Slope(p1, p2, dx, dy);
}
function newSlopeFromAngle(angle) {
  return newSlope(
    0,
    0,
    Math.cos(angle * DEG2RAD2),
    Math.sin(angle * DEG2RAD2)
  );
}

