var History = class {
  #pos = -1;
  #stack = [];
  #offset;
  // store final drag move
  #target;
  // store sketch drag target
  #tracking = false;
  constructor() {
    broker.subscribe({
      app_ready() {
        this.#tracking = true;
      },
      drag_start(selected3) {
      },
      drag(opt) {
        this.#target = target();
        this.#offset = opt.offset;
      },
      drag_end(selected3) {
        const { x: x2, y: y2, z: z2 } = this.#offset;
        broker.publish("move", {
          target: this.#target,
          set: selected3,
          dx: x2,
          dy: y2,
          dz: z2
        });
      },
      move(data2) {
        const { target: target2, set, dx, dy, dz } = data2;
        this.push("move", {
          set,
          dx: -dx,
          dy: -dy,
          dz: -dz,
          target: target2
        }, {
          set,
          dx,
          dy,
          dz,
          target: target2
        });
      },
      rotate(data2) {
        const { set, dx, dy, dz } = data2;
        this.push("rotate", {
          set,
          dx: -dx,
          dy: -dy,
          dz: -dz
        }, {
          set,
          dx,
          dy,
          dz
        });
      },
      scale(data2) {
        const { set, dx, dy, dz } = data2;
        this.push("scale", {
          set,
          dx: 1 / dx,
          dy: 1 / dy,
          dz: 1 / dz
        }, {
          set,
          dx,
          dy,
          dz
        });
      }
    }, this);
  }
  push(type2, undo, redo) {
    this.#stack.length = ++this.#pos;
    this.#stack.push({
      type: type2,
      undo,
      redo
    });
  }
  // update(redo, undo) {
  //     let peek = this.#stack.peek();
  //     if (peek) {
  //         Object.assign(peek, {
  //             redo: redo || peek.redo,
  //             undo: undo || peek.undo
  //         });
  //     }
  // }
  do(type2, data2) {
    switch (type2) {
      case "move": {
        let { set, dx, dy, dz, target: target2 } = data2;
        for (let grp of set) {
          grp.move(dx, dy, dz, target2);
        }
        break;
      }
      // case 'position': {
      //     for (let { model, pos } of data) {
      //         model.position(...pos);
      //     }
      //     break;
      // }
      case "rotate": {
        let { set, dx, dy, dz } = data2;
        for (let grp of set) {
          grp.rotate(dx, dy, dz);
        }
        break;
      }
      case "scale": {
        let { set, dx, dy, dz } = data2;
        for (let grp of set) {
          grp.scale(dx, dy, dz);
        }
        break;
      }
      default:
        console.warn(`invalid record type: ${type2}`);
    }
  }
  undo() {
    if (this.#pos >= 0) {
      const rec = this.#stack[this.#pos--];
      this.do(rec.type, rec.undo);
      broker.publish("history_undo", rec);
    }
  }
  redo() {
    if (this.#stack.length && this.#pos >= -1 && this.#pos < this.#stack.length - 1) {
      const rec = this.#stack[++this.#pos];
      this.do(rec.type, rec.redo);
      broker.publish("history_redo", rec);
    }
  }
};
