var script = {
  running: false,
  visible: false,
  changed() {
    localStorage.script = $2("script-editor").value;
  },
  error(e) {
    api3.modal.dialog({
      title: "script error",
      body: [h.div({ id: "script-error", _: e.message || e.toString() })]
    });
  },
  hide() {
    $2("script").classList.add("hide");
    api3.prefs.save(api3.prefs.map.space.script = script.visible = false);
  },
  show() {
    $2("script").classList.remove("hide");
    $2("script-editor").value = localStorage.script ?? "";
    api3.prefs.save(api3.prefs.map.space.script = script.visible = true);
  },
  toggle() {
    if (script.visible) {
      script.hide();
    } else {
      script.show();
    }
  },
  execute() {
    let cmd = localStorage.script || `console.log('no script')`;
    if (cmd) {
      if (script.running) {
        return script.error("script running");
      }
      cmd = [
        "(async () => {",
        cmd,
        "})()",
        ".catch(error => {",
        "api.script.error(error)",
        "})",
        ".finally(() => {",
        "api.script.running = false;",
        "});"
      ].join("\n");
      try {
        eval(`{ 
 ${cmd} 
 }`);
      } catch (e) {
        script.error(e);
      }
    }
  }
};

