// src/kiri/mode/cam/app/cl-origin.js
var originSelectOn = false;
var { world } = api2.const.SPACE;
var alert7;
var lastHover;
var lastPoints;
function originSelect() {
  if (originSelectOn) {
    return originSelectDone();
  }
  clearPops();
  alert7 = api2.show.alert("analyzing parts...", 1e3);
  originSelectOn = true;
  api2.feature.hover = true;
  api2.feature.hoverAdds = true;
  env.hover = pointHover;
  env.hoverUp = pointHoverUp;
  function updateKey(pt) {
    pt._key = [
      pt.x * 1e3 | 0,
      pt.y * 1e3 | 0,
      pt.z * 1e3 | 0
    ].join(" ");
    return pt;
  }
  CAM2.traces((ids) => {
    api2.hide.alert(alert7);
    alert7 = api2.show.alert("select origin<br>[esc] to cancel", 1e3);
    let ends = {};
    let points2 = {};
    let color3 = new THREE.Color(16711680);
    function incpoint(widget, point) {
      let rec = ends[point.key];
      if (rec && rec.count++ === 2) {
        addpoint(widget, point);
      } else if (!rec) {
        rec = ends[point.key] = { count: 1 };
      }
    }
    function addpoint(widget, center) {
      let box = addbox(center, color3, void 0, void 0, { opacity: 1 });
      widget.adds.push(box);
      world.add(box);
      box._origin = center;
      points2[center.key] = { box, center };
    }
    api2.widgets.for((widget) => {
      let { pos, tzoff } = widget.track;
      let polys = widget.traces.map((trace) => {
        return trace.fixClosed().clone().move(pos).move({ x: 0, y: 0, z: -tzoff });
      });
      for (let poly of polys) {
        if (poly.circularity() >= 0.99) {
          let center = updateKey(poly.calcCircleCenter());
          if (points2[center.key]) {
            continue;
          }
          addpoint(widget, center);
        } else if (poly.isOpen()) {
          incpoint(widget, updateKey(poly.first()));
          incpoint(widget, updateKey(poly.last()));
        }
      }
    });
    lastPoints = Object.values(points2);
  });
}
function originReset() {
  let { process: process3 } = api2.conf.get();
  process3.camOriginOffX = 0;
  process3.camOriginOffY = 0;
  process3.camOriginOffZ = 0;
  api2.settings.update_fields(process3);
  api2.platform.update_origin();
  api2.conf.save();
  originSelectDone();
}
function originSelectDone() {
  if (!originSelectOn) {
    return;
  }
  api2.hide.alert(alert7);
  api2.feature.hover = false;
  api2.feature.hoverAdds = false;
  api2.widgets.for((widget) => {
    for (let box of widget.adds) {
      world.remove(box);
    }
    widget.adds.length = 0;
  });
  clearboxes();
  originSelectOn = false;
}
function pointHover(data2) {
  if (lastHover) {
    let { color: color5, colorSave } = lastHover.material[0] || lastHover.material;
    color5.r = colorSave.r;
    color5.g = colorSave.g;
    color5.b = colorSave.b;
  }
  lastHover = null;
  if (data2.type === "platform") {
    return;
  }
  if (!data2.int.object._origin) {
    return;
  }
  lastHover = data2.int.object;
  let material4 = lastHover.material[0] || lastHover.material;
  let color3 = material4.color;
  material4.colorSave = color3.clone();
  color3.setHex(65280);
}
function pointHoverUp(int, ev) {
  if (!int?.object?._origin) return;
  let { _origin: _origin2 } = int.object;
  let { process: process3, stock } = api2.conf.get();
  let { x: x2, y: y2, z: z2 } = _origin2;
  let { camOriginTop, camOriginCenter } = process3;
  if (camOriginTop) {
    z2 = z2 - stock.z;
  }
  if (!camOriginCenter) {
    x2 += stock.x / 2;
    y2 += stock.y / 2;
  }
  process3.camOriginOffX = x2 - stock.center.x;
  process3.camOriginOffY = y2 - stock.center.y;
  process3.camOriginOffZ = z2;
  api2.settings.update_fields(process3);
  api2.platform.update_origin();
  api2.conf.save();
  originSelectDone();
}

